3	/// What the assistant's responses cost, on the app's side (road map 13 P2,
4	/// spec §11 P-4, P-5): the spend folder, the price-table fields `configure`
5	/// carries, the ledger line each `cost` event becomes, the view of an event a
6	/// dev tool may return, and the turn's cost line. The helper prices every
7	/// response (`agent/src/priceTable.ts`, `pricing.ts`); this file only records
8	/// the dollars it computed and formats them and their dates. No pricing
9	/// arithmetic is done here (road map 13 §2).
10	///
11	/// **P-5, the rule this file keeps.** The ledger (`spend.jsonl`) and the price
12	/// cache (`anthropic-prices.json`) are the person's, in the spend folder,
13	/// Frame Job's own folder in Application Support. `-RCSpendFolder <path>`,
14	/// read from the ARGUMENT domain alone (`AssemblyAIConfiguration.argument`,
15	/// R6-9 (c)), replaces it. With `RC_ASSISTANT_BASE_URL` set and no
16	/// `-RCSpendFolder` there is no spend folder: nothing is written and the
17	/// helper prices from its bundled table. With the base URL set, the cache is
18	/// handed to the helper only together with `-RCPriceFeed`, so a proof never
19	/// reaches LiteLLM. The support folder is named in exactly one line of this
20	/// file, as in `AssistantConfiguration.swift`; the folder is created, at
21	/// 0700, by whichever comes first: a ledger line written (`record`) or the
22	/// helper's cache write (`refreshPrices`, `mkdir -p`).
23	///
24	/// **Never the key, never content.** A ledger line carries the keys
25	/// `ledgerLine` lists and nothing else; `usage` is whitelisted field by field.
26	enum AssistantSpend {
27	    static let folderArgument = "RCSpendFolder", feedArgument = "RCPriceFeed",
28	        ledgerName = "spend.jsonl", priceCacheName = "anthropic-prices.json"
29	    /// Posted by `record` (object nil, on its caller's thread — main in the
30	    /// app) each time it writes a ledger line; Settings' month figure
31	    /// re-reads the ledger on it (spec §11 P-7).
32	    static let didRecordNotification = Notification.Name("FrameJobSpendDidRecord")
33	
34	    /// The token counts a ledger line keeps from a `usage` or an iteration.
35	    private static let countKeys = [
36	        "input_tokens", "output_tokens", "cache_creation_input_tokens", "cache_read_input_tokens",
37	    ]
38	    /// The split of cache writes under `usage.cache_creation`.
39	    private static let splitKeys = ["ephemeral_5m_input_tokens", "ephemeral_1h_input_tokens"]
40	    /// The modes `usage` names, which decide whether a response is priced.
41	    private static let modeKeys = ["service_tier", "speed", "inference_geo"]
42	
43	    /// The spend folder, or nil when there is none (P-5).
44	    static func folder(
45	        defaults: UserDefaults = .standard,
46	        environment: [String: String] = ProcessInfo.processInfo.environment
47	    ) -> URL? {
48	        if let path = AssemblyAIConfiguration.argument(folderArgument, defaults: defaults) {
49	            return URL(
50	                fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true)
51	        }
52	        if let base = environment[AssistantConfiguration.baseURLVariable], !base.isEmpty {
53	            return nil
54	        }
55	        return AppSupport.directory
56	    }
