77	    /// The ledger line of a `cost` event, else nil: `time` (ISO 8601 UTC),
78	    /// `service`, `model`, the whitelisted `usage`, `dollars` (or null),
79	    /// `unknown` (null or `{cause, detail}`), `rows` (only when priced),
80	    /// `prices` (`{kind, as_of, problem?}`) and `partial: true` for a response
81	    /// cut short (spec §11 P-8), absent otherwise. Nothing else.
82	    static func ledgerLine(_ event: [String: Any], at time: Date) -> [String: Any]? {
83	        guard event["type"] as? String == "cost" else { return nil }
84	        let cost = event["cost"] as? [String: Any] ?? [:]
85	        var line: [String: Any] = [
86	            "time": ISO8601DateFormatter().string(from: time),
87	            "service": "anthropic",
88	            "model": (event["model"] as? String).map { $0 as Any } ?? NSNull(),
89	            "usage": usage(event["usage"]),
90	            "prices": prices(event["prices"]),
91	            "dollars": NSNull(), "unknown": NSNull(),
92	        ]
93	        if cost["kind"] as? String == "dollars", let dollars = number(cost["dollars"]) {
94	            line["dollars"] = dollars
95	            line["rows"] = (cost["rows"] as? [Any] ?? []).compactMap { $0 as? String }
96	        } else {
97	            line["unknown"] = [
98	                "cause": cost["cause"] as? String ?? "usage",
99	                "detail": cost["detail"] as? String ?? "the helper sent no price",
100	            ]
101	        }
102	        if isPartial(event) { line["partial"] = true }
103	        return line
104	    }
105	
106	    /// Whether `event` is a response cut short (P-8): only a JSON `true`.
107	    static func isPartial(_ event: [String: Any]) -> Bool {
108	        guard let flag = event["partial"] as? NSNumber,
109	            CFGetTypeID(flag) == CFBooleanGetTypeID()
110	        else { return false }
111	        return flag.boolValue
112	    }
113	
114	    /// Appends `event`'s ledger line to `spend.jsonl` in `folder`, creating
115	    /// the folder first; the file is opened `O_APPEND|O_CREAT` at 0600 and
116	    /// the line written in one `write`. Nil when written or when there is
117	    /// nothing to write (not a `cost`, no spend folder); else the failure, in
118	    /// a sentence the transcript can show.
119	    static func record(_ event: [String: Any], in folder: URL?, at time: Date = Date()) -> String? {
120	        guard let line = ledgerLine(event, at: time), let folder else { return nil }
121	        let path = folder.appendingPathComponent(ledgerName).path
122	        func failure(_ reason: String) -> String {
123	            let bare = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
124	            return "The spend ledger \(path) could not be written: \(bare)."
125	        }
126	        do {
127	            try AppSupport.ensureDirectory(folder)
128	        } catch {
129	            return failure(error.localizedDescription)
130	        }
131	        guard var data = try? JSONSerialization.data(withJSONObject: line, options: [.sortedKeys])
132	        else { return failure("the line is not JSON") }
133	        data.append(UInt8(ascii: "\n"))
134	        let descriptor = open(path, O_WRONLY | O_APPEND | O_CREAT, 0o600)
135	        guard descriptor >= 0 else { return failure(String(cString: strerror(errno))) }
136	        defer { close(descriptor) }
137	        let written = data.withUnsafeBytes { write(descriptor, $0.baseAddress, $0.count) }
138	        guard written == data.count else {
139	            return failure(written < 0 ? String(cString: strerror(errno)) : "a short write")
140	        }
141	        NotificationCenter.default.post(name: didRecordNotification, object: nil)
142	        return nil
143	    }
144	
145	    /// An event as a dev tool may return it (AI-8, AI-11: never the key or
146	    /// the model): a `cost` keeps only `{type, cost: {kind, dollars|cause},
147	    /// prices}` and `partial: true` for one cut short; every other event is itself.
148	    static func toolView(_ event: [String: Any]) -> [String: Any] {
149	        guard event["type"] as? String == "cost" else { return event }
150	        let cost = event["cost"] as? [String: Any] ?? [:]
151	        var view: [String: Any] = ["kind": cost["kind"] ?? NSNull()]
152	        if cost["kind"] as? String == "dollars" {
153	            view["dollars"] = cost["dollars"] ?? NSNull()
154	        } else {
155	            view["cause"] = cost["cause"] ?? NSNull()
156	        }
157	        var kept: [String: Any] = [
158	            "type": "cost", "cost": view, "prices": prices(event["prices"]),
159	        ]
160	        if isPartial(event) { kept["partial"] = true }
161	        return kept
162	    }
