164	    /// An ISO 8601 instant, with whole or fractional seconds; nil otherwise.
165	    /// The two parsers are built once: a month's fold calls this per line.
166	    static func instant(_ text: String) -> Date? {
167	        wholeSeconds.date(from: text) ?? fractionalSeconds.date(from: text)
168	    }
169	
170	    private static let wholeSeconds = ISO8601DateFormatter()
171	    private static let fractionalSeconds: ISO8601DateFormatter = {
172	        let parser = ISO8601DateFormatter()
173	        parser.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
174	        return parser
175	    }()
176	
177	    /// A JSON number that is not a boolean.
178	    static func number(_ value: Any?) -> NSNumber? {
179	        guard let value = value as? NSNumber, CFGetTypeID(value) != CFBooleanGetTypeID()
180	        else { return nil }
181	        return value
182	    }
183	
184	    // MARK: - Private
185	
186	    private static func counts(_ from: [String: Any], into: inout [String: Any]) {
187	        for key in countKeys { if let value = number(from[key]) { into[key] = value } }
188	        if let split = from["cache_creation"] as? [String: Any] {
189	            var kept: [String: Any] = [:]
190	            for key in splitKeys { if let value = number(split[key]) { kept[key] = value } }
191	            into["cache_creation"] = kept
192	        }
193	    }
194	
195	    private static func usage(_ value: Any?) -> [String: Any] {
196	        guard let usage = value as? [String: Any] else { return [:] }
197	        var kept: [String: Any] = [:]
198	        counts(usage, into: &kept)
199	        for key in modeKeys { if let mode = usage[key] as? String { kept[key] = mode } }
200	        if let iterations = usage["iterations"] as? [Any] {
201	            kept["iterations"] = iterations.map { element -> [String: Any] in
202	                guard let entry = element as? [String: Any] else { return [:] }
203	                var one: [String: Any] = [:]
204	                for key in ["type", "model"] { if let text = entry[key] as? String { one[key] = text } }
205	                counts(entry, into: &one)
206	                return one
207	            }
208	        }
209	        return kept
210	    }
211	
212	    private static func prices(_ value: Any?) -> [String: Any] {
213	        let source = value as? [String: Any] ?? [:]
214	        var kept: [String: Any] = [
215	            "kind": source["kind"] as? String ?? "unknown", "as_of": source["as_of"] as? String ?? "",
216	        ]
217	        if let problem = source["problem"] as? String { kept["problem"] = problem }
218	        return kept
219	    }
