398	      const resolve = pendingCalls.get(message.call_id);
399	      pendingCalls.delete(message.call_id);
400	      resolve?.(message.result);
401	      break;
402	    }
403	    case "settings":
404	      // Applies from the next turn; a running turn keeps what it started with.
405	      settings = message.settings;
406	      break;
407	    case "reset":
408	      turn?.abort();
409	      history = [];
410	      contextUsed = 0;
411	      emitContextUsage();
412	      break;
413	  }
414	}
415	
416	const input = createInterface({ input: process.stdin });
417	input.on("line", (line) => {
418	  if (!line.trim()) return;
419	  try {
420	    handle(JSON.parse(line) as HostMessage);
421	  } catch (error) {
422	    emit({ type: "error", message: `Bad message from the app: ${errorMessage(error)}` });
423	  }
424	});
425	// The app closing our stdin means it is gone or closed the session.
426	input.on("close", () => process.exit(0));
