3	/// What the assistant's responses cost, on the app's side (road map 13 P2,
4	/// spec §11 P-4, P-5): the spend folder, the price-table fields `configure`
5	/// carries, the ledger line each `cost` event becomes, the view of an event a
6	/// dev tool may return, and the turn's cost line. The helper prices every
7	/// response (`agent/src/priceTable.ts`, `pricing.ts`); this file only records
8	/// the dollars it computed and formats them and their dates. No pricing
9	/// arithmetic is done here (road map 13 §2).
10	///
11	/// **P-5, the rule this file keeps.** The ledger (`spend.jsonl`) and the price
12	/// cache (`anthropic-prices.json`) are the person's, in the spend folder,
13	/// Frame Job's own folder in Application Support. `-RCSpendFolder <path>`,
14	/// read from the ARGUMENT domain alone (`AssemblyAIConfiguration.argument`,
15	/// R6-9 (c)), replaces it. With `RC_ASSISTANT_BASE_URL` set and no
16	/// `-RCSpendFolder` there is no spend folder: nothing is written and the
17	/// helper prices from its bundled table. With the base URL set, the cache is
18	/// handed to the helper only together with `-RCPriceFeed`, so a proof never
19	/// reaches LiteLLM. The support folder is named in exactly one line of this
20	/// file, as in `AssistantConfiguration.swift`; the folder is created, at
21	/// 0700, by whichever comes first: a ledger line written (`record`) or the
22	/// helper's cache write (`refreshPrices`, `mkdir -p`).
23	///
24	/// **Never the key, never content.** A ledger line carries the keys
25	/// `ledgerLine` lists and nothing else; `usage` is whitelisted field by field.
26	enum AssistantSpend {
27	    static let folderArgument = "RCSpendFolder", feedArgument = "RCPriceFeed",
28	        ledgerName = "spend.jsonl", priceCacheName = "anthropic-prices.json"
29	    /// Posted by `record` (object nil, on its caller's thread — main in the
30	    /// app) each time it writes a ledger line; Settings' month figure
31	    /// re-reads the ledger on it (spec §11 P-7).
32	    static let didRecordNotification = Notification.Name("FrameJobSpendDidRecord")
33	
34	    /// The token counts a ledger line keeps from a `usage` or an iteration.
35	    private static let countKeys = [
36	        "input_tokens", "output_tokens", "cache_creation_input_tokens", "cache_read_input_tokens",
37	    ]
38	    /// The split of cache writes under `usage.cache_creation`.
39	    private static let splitKeys = ["ephemeral_5m_input_tokens", "ephemeral_1h_input_tokens"]
40	    /// The modes `usage` names, which decide whether a response is priced.
41	    private static let modeKeys = ["service_tier", "speed", "inference_geo"]
42	
43	    /// The spend folder, or nil when there is none (P-5).
44	    static func folder(
45	        defaults: UserDefaults = .standard,
46	        environment: [String: String] = ProcessInfo.processInfo.environment
47	    ) -> URL? {
48	        if let path = AssemblyAIConfiguration.argument(folderArgument, defaults: defaults) {
49	            return URL(
50	                fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true)
51	        }
52	        if let base = environment[AssistantConfiguration.baseURLVariable], !base.isEmpty {
53	            return nil
54	        }
55	        return AppSupport.directory
56	    }
57	
58	    /// `configure`'s `price_cache` and `price_feed` (`agent/src/protocol.ts`):
59	    /// the cache in the spend folder, when there is one and, with the
60	    /// base-URL override set, only beside `-RCPriceFeed`.
61	    static func configureFields(
62	        defaults: UserDefaults = .standard,
63	        environment: [String: String] = ProcessInfo.processInfo.environment
64	    ) -> [String: Any] {
65	        var fields: [String: Any] = [:]
66	        let feed = AssemblyAIConfiguration.argument(feedArgument, defaults: defaults)
67	        if let feed { fields["price_feed"] = feed }
68	        guard let folder = folder(defaults: defaults, environment: environment) else {
69	            return fields
70	        }
71	        let overridden = !(environment[AssistantConfiguration.baseURLVariable] ?? "").isEmpty
72	        if overridden && feed == nil { return fields }
73	        fields["price_cache"] = folder.appendingPathComponent(priceCacheName).path
74	        return fields
75	    }
76	
77	    /// The ledger line of a `cost` event, else nil: `time` (ISO 8601 UTC),
78	    /// `service`, `model`, the whitelisted `usage`, `dollars` (or null),
79	    /// `unknown` (null or `{cause, detail}`), `rows` (only when priced),
80	    /// `prices` (`{kind, as_of, problem?}`) and `partial: true` for a response
81	    /// cut short (spec §11 P-8), absent otherwise. Nothing else.
82	    static func ledgerLine(_ event: [String: Any], at time: Date) -> [String: Any]? {
83	        guard event["type"] as? String == "cost" else { return nil }
84	        let cost = event["cost"] as? [String: Any] ?? [:]
85	        var line: [String: Any] = [
86	            "time": ISO8601DateFormatter().string(from: time),
87	            "service": "anthropic",
88	            "model": (event["model"] as? String).map { $0 as Any } ?? NSNull(),
89	            "usage": usage(event["usage"]),
90	            "prices": prices(event["prices"]),
91	            "dollars": NSNull(), "unknown": NSNull(),
92	        ]
93	        if cost["kind"] as? String == "dollars", let dollars = number(cost["dollars"]) {
94	            line["dollars"] = dollars
95	            line["rows"] = (cost["rows"] as? [Any] ?? []).compactMap { $0 as? String }
96	        } else {
97	            line["unknown"] = [
98	                "cause": cost["cause"] as? String ?? "usage",
99	                "detail": cost["detail"] as? String ?? "the helper sent no price",
100	            ]
101	        }
102	        if isPartial(event) { line["partial"] = true }
103	        return line
104	    }
105	
106	    /// Whether `event` is a response cut short (P-8): only a JSON `true`.
107	    static func isPartial(_ event: [String: Any]) -> Bool {
108	        guard let flag = event["partial"] as? NSNumber,
109	            CFGetTypeID(flag) == CFBooleanGetTypeID()
110	        else { return false }
111	        return flag.boolValue
112	    }
113	
114	    /// Appends `event`'s ledger line to `spend.jsonl` in `folder`, creating
115	    /// the folder first; the file is opened `O_APPEND|O_CREAT` at 0600 and
116	    /// the line written in one `write`. Nil when written or when there is
117	    /// nothing to write (not a `cost`, no spend folder); else the failure, in
118	    /// a sentence the transcript can show.
119	    static func record(_ event: [String: Any], in folder: URL?, at time: Date = Date()) -> String? {
120	        guard let line = ledgerLine(event, at: time), let folder else { return nil }
121	        let path = folder.appendingPathComponent(ledgerName).path
122	        func failure(_ reason: String) -> String {
123	            let bare = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
124	            return "The spend ledger \(path) could not be written: \(bare)."
125	        }
126	        do {
127	            try AppSupport.ensureDirectory(folder)
128	        } catch {
129	            return failure(error.localizedDescription)
130	        }
131	        guard var data = try? JSONSerialization.data(withJSONObject: line, options: [.sortedKeys])
132	        else { return failure("the line is not JSON") }
133	        data.append(UInt8(ascii: "\n"))
134	        let descriptor = open(path, O_WRONLY | O_APPEND | O_CREAT, 0o600)
135	        guard descriptor >= 0 else { return failure(String(cString: strerror(errno))) }
136	        defer { close(descriptor) }
137	        let written = data.withUnsafeBytes { write(descriptor, $0.baseAddress, $0.count) }
138	        guard written == data.count else {
139	            return failure(written < 0 ? String(cString: strerror(errno)) : "a short write")
140	        }
141	        NotificationCenter.default.post(name: didRecordNotification, object: nil)
142	        return nil
143	    }
144	
145	    /// An event as a dev tool may return it (AI-8, AI-11: never the key or
146	    /// the model): a `cost` keeps only `{type, cost: {kind, dollars|cause},
147	    /// prices}` and `partial: true` for one cut short; every other event is itself.
148	    static func toolView(_ event: [String: Any]) -> [String: Any] {
149	        guard event["type"] as? String == "cost" else { return event }
150	        let cost = event["cost"] as? [String: Any] ?? [:]
151	        var view: [String: Any] = ["kind": cost["kind"] ?? NSNull()]
152	        if cost["kind"] as? String == "dollars" {
153	            view["dollars"] = cost["dollars"] ?? NSNull()
154	        } else {
155	            view["cause"] = cost["cause"] ?? NSNull()
156	        }
157	        var kept: [String: Any] = [
158	            "type": "cost", "cost": view, "prices": prices(event["prices"]),
159	        ]
160	        if isPartial(event) { kept["partial"] = true }
161	        return kept
162	    }
163	
164	    /// An ISO 8601 instant, with whole or fractional seconds; nil otherwise.
165	    /// The two parsers are built once: a month's fold calls this per line.
166	    static func instant(_ text: String) -> Date? {
167	        wholeSeconds.date(from: text) ?? fractionalSeconds.date(from: text)
168	    }
169	
170	    private static let wholeSeconds = ISO8601DateFormatter()
171	    private static let fractionalSeconds: ISO8601DateFormatter = {
172	        let parser = ISO8601DateFormatter()
173	        parser.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
174	        return parser
175	    }()
176	
177	    /// A JSON number that is not a boolean.
178	    static func number(_ value: Any?) -> NSNumber? {
179	        guard let value = value as? NSNumber, CFGetTypeID(value) != CFBooleanGetTypeID()
180	        else { return nil }
181	        return value
182	    }
183	
184	    // MARK: - Private
185	
186	    private static func counts(_ from: [String: Any], into: inout [String: Any]) {
187	        for key in countKeys { if let value = number(from[key]) { into[key] = value } }
188	        if let split = from["cache_creation"] as? [String: Any] {
189	            var kept: [String: Any] = [:]
190	            for key in splitKeys { if let value = number(split[key]) { kept[key] = value } }
191	            into["cache_creation"] = kept
192	        }
193	    }
194	
195	    private static func usage(_ value: Any?) -> [String: Any] {
196	        guard let usage = value as? [String: Any] else { return [:] }
197	        var kept: [String: Any] = [:]
198	        counts(usage, into: &kept)
199	        for key in modeKeys { if let mode = usage[key] as? String { kept[key] = mode } }
200	        if let iterations = usage["iterations"] as? [Any] {
201	            kept["iterations"] = iterations.map { element -> [String: Any] in
202	                guard let entry = element as? [String: Any] else { return [:] }
203	                var one: [String: Any] = [:]
204	                for key in ["type", "model"] { if let text = entry[key] as? String { one[key] = text } }
205	                counts(entry, into: &one)
206	                return one
207	            }
208	        }
209	        return kept
210	    }
211	
212	    private static func prices(_ value: Any?) -> [String: Any] {
213	        let source = value as? [String: Any] ?? [:]
214	        var kept: [String: Any] = [
215	            "kind": source["kind"] as? String ?? "unknown", "as_of": source["as_of"] as? String ?? "",
216	        ]
217	        if let problem = source["problem"] as? String { kept["problem"] = problem }
218	        return kept
219	    }
220	}
221	
222	/// One turn's cost, summed from its `cost` events: the dollars the helper
223	/// computed, the first response it could not price, and the table the last
224	/// response was priced from. `line` is the transcript's `.meta` line; a turn
225	/// with no `cost` event has none. Unknown is never shown as $0 (P-2); a
226	/// response cut short makes the priced amount "at least" (P-8).
227	struct AssistantTurnCost: Equatable {
228	    private var responses = 0
229	    private var dollars = 0.0
230	    private var priced = false
231	    private var firstUnknown: String?
232	    private var partial = false
233	    private var kind = "", asOf = "", problem: String?
234	
235	    mutating func add(_ event: [String: Any]) {
236	        guard event["type"] as? String == "cost" else { return }
237	        responses += 1
238	        if AssistantSpend.isPartial(event) { partial = true }
239	        let cost = event["cost"] as? [String: Any] ?? [:]
240	        if cost["kind"] as? String == "dollars", let value = cost["dollars"] as? Double {
241	            dollars += value
242	            priced = true
243	        } else if firstUnknown == nil {
244	            firstUnknown = cost["detail"] as? String ?? "no price"
245	        }
246	        let source = event["prices"] as? [String: Any] ?? [:]
247	        kind = source["kind"] as? String ?? ""
248	        asOf = source["as_of"] as? String ?? ""
249	        problem = source["problem"] as? String
250	    }
251	
252	    var line: String? {
253	        guard responses > 0 else { return nil }
254	        var amount = Self.amount(dollars)
255	        if let firstUnknown {
256	            amount = "unknown (\(firstUnknown))"
257	            if priced { amount += Self.pricedPart(dollars) }
258	        } else if partial {
259	            amount = Self.lowerBound(dollars) + " (a response was cut short)"
260	        }
261	        let day = Self.day(asOf)
262	        var source: String
263	        switch kind {
264	        case "bundled": source = "bundled table of \(day)"
265	        case "cached": source = "cached \(day)"
266	        case "fetched": source = "fetched \(day)"
267	        default: source = "\(kind) \(day)"
268	        }
269	        // A fetched table was refreshed; its problem is the cache write.
270	        if let problem { source += (kind == "fetched" ? "; " : "; not refreshed: ") + problem }
271	        return "Cost: \(amount) · Frame Job's estimate at LiteLLM prices (\(source))"
272	    }
273	
274	    /// The Assistant tab's Spend row (spec §11 P-7): "Nothing yet" before any
275	    /// response; the amount when every response was priced, "at least" it
276	    /// when one was cut short; "at least" the priced part when one was not
277	    /// priced and the part shows; else "unknown".
278	    var figure: String {
279	        guard responses > 0 else { return "Nothing yet" }
280	        let estimate = " · Frame Job's estimate"
281	        if firstUnknown == nil {
282	            return (partial ? Self.lowerBound(dollars) : Self.amount(dollars)) + estimate
283	        }
284	        if dollars >= 0.000_05 { return "at least " + String(format: "$%.4f", dollars) + estimate }
285	        return "unknown" + estimate
286	    }
287	
288	    /// The Spend row's spellings, longest first (spec §11 P-7, P-8):
289	    /// ["Nothing yet"] before any response; else [figure], plus, when figure
290	    /// starts "at least " or "under ", figure with that prefix replaced by
291	    /// "≥" or "<" (no space). Every rung after a response ends
292	    /// " · Frame Job's estimate".
293	    var figureLadder: [String] {
294	        let full = figure
295	        for (long, short) in [("at least ", "≥"), ("under ", "<")] where full.hasPrefix(long) {
296	            return [full, short + full.dropFirst(long.count)]
297	        }
298	        return [full]
299	    }
300	
301	    static let figureTooltip =
302	        "What this conversation's responses cost at LiteLLM prices, as Frame Job estimates it. "
303	        + "The Anthropic Console shows what your account was billed."
304	
305	    /// `$%.4f`, or `under $0.0001` for a positive amount that would round to 0.
306	    static func amount(_ dollars: Double) -> String {
307	        if dollars > 0 && dollars < 0.000_05 { return "under $0.0001" }
308	        return String(format: "$%.4f", dollars)
309	    }
310	
311	    /// A lower bound (P-8): `at least $%.4f`, or `amount` below $0.00005.
312	    static func lowerBound(_ dollars: Double) -> String {
313	        dollars < 0.000_05 ? amount(dollars) : "at least " + String(format: "$%.4f", dollars)
314	    }
315	
316	    /// What the priced responses of a turn with an unknown one came to:
317	    /// ` · at least $%.4f`, or ` · the priced part under $0.0001` for a
318	    /// positive amount that would round to 0.
319	    static func pricedPart(_ dollars: Double) -> String {
320	        if dollars > 0 && dollars < 0.000_05 { return " · the priced part under $0.0001" }
321	        return " · at least " + String(format: "$%.4f", dollars)
322	    }
323	
324	    /// The `yyyy-MM-dd` of the ISO 8601 instant `asOf` in `zone`; its first 10
